WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/56.0/connection.js")}
{!REQUIRESCRIPT("/soap/ajax/56.0/apex.js")}

var query = "select Id,Restricted_Re_booking_Time__c,Last_Booked_By__c from Inventory__c where Id = '{!Inventory__c.Id}' limit 1";

var result = sforce.connection.query(query);
var records = result.getArray("records");

var myObj = records[0];
if(myObj.Restricted_Re_booking_Time__c != null || myObj.Last_Booked_By__c != null){
myObj.Restricted_Re_booking_Time__c = null;
myObj.Last_Booked_By__c = null;

var result = sforce.connection.update([myObj]);

if (result[0].getBoolean("success")) {
alert("Blocking removed Successfully!");
window.location.reload();
} else {
alert("failed to update Inventory." + result[0]);
window.location.reload();
}
}else{
alert("This unit is not blocked for Sales Consultant!");
window.location.reload();
}
